import numpy as np, itertools
def norm(v): return v/np.linalg.norm(v)
dTcP=2.42; dTcS=2.33; dPC=1.84; dCH=1.09; dSC=1.82

def tet_H(C,nbrs,n_h,phase=0.0,bl=dCH):
    dirs=[norm(n-C) for n in nbrs]; out=[]
    if len(dirs)==1:
        u=dirs[0]; t=np.array([0,0,1.0])
        if abs(np.dot(t,u))>0.9: t=np.array([1.0,0,0])
        a=norm(np.cross(u,t)); b=np.cross(u,a)
        for k in range(n_h):
            th=2*np.pi*k/3+phase
            d=-np.cos(np.deg2rad(70.5))*u+np.sin(np.deg2rad(70.5))*(np.cos(th)*a+np.sin(th)*b)
            out.append(C+bl*norm(d))
    else:
        s=norm(dirs[0]+dirs[1]); p=norm(np.cross(dirs[0],dirs[1]))
        for sg in (1,-1):
            d=-np.cos(np.deg2rad(54.75))*s+sg*np.sin(np.deg2rad(54.75))*p
            out.append(C+bl*norm(d))
    return out

def place_P(phi,phi_partner,zsign):
    ph=np.deg2rad(phi); u=np.array([np.cos(ph),np.sin(ph),0.])
    P=dTcP*u; t=np.array([-np.sin(ph),np.cos(ph),0.])
    pp=np.deg2rad(phi_partner); up=np.array([np.cos(pp),np.sin(pp),0.])
    a=norm(t*np.sign(np.dot(t,up))); b=np.array([0,0,1.0])*zsign
    ang=np.deg2rad(70.5); ds=[]
    for th in (0,120,240):
        th=np.deg2rad(th)
        ds.append(norm(np.cos(ang)*u+np.sin(ang)*(np.cos(th)*a+np.sin(th)*b)))
    return P,ds

def build(smeaz, ph_me, ph_sme):
    atoms=[]
    def add(e,p): atoms.append((e,np.array(p,float)))
    add('Tc',[0,0,0])
    for (pa,pb,zs) in [(42,-42,1),(138,222,-1)]:
        PA,dA=place_P(pa,pb,zs); PB,dB=place_P(pb,pa,zs)
        add('P',PA); add('P',PB)
        CA=PA+dPC*dA[0]; CB=PB+dPC*dB[0]
        add('C',CA); add('C',CB)
        for P,ds in ((PA,dA),(PB,dB)):
            for d in ds[1:]:
                Cm=P+dPC*d; add('C',Cm)
                for h in tet_H(Cm,[P],3,ph_me): add('H',h)
        for h in tet_H(CA,[PA,CB],2): add('H',h)
        for h in tet_H(CB,[PB,CA],2): add('H',h)
    for sgn,az in ((1,smeaz),(-1,smeaz+180)):
        S=np.array([0,0,dTcS*sgn]); add('S',S)
        a=np.deg2rad(az)
        d=norm(np.array([0.94*np.cos(a),0.94*np.sin(a),0.342*sgn]))
        C=S+dSC*d; add('C',C)
        for h in tet_H(C,[S],3,ph_sme): add('H',h)
    return atoms

best=None
for smeaz in range(0,360,10):
    for ph_me in range(0,120,15):
        for ph_sme in range(0,120,15):
            at=build(smeaz,np.deg2rad(ph_me),np.deg2rad(ph_sme))
            pos=np.array([p for e,p in at])
            n=len(at)
            D=np.linalg.norm(pos[:,None]-pos[None],axis=-1)+np.eye(n)*99
            # only consider pairs not bonded: use threshold on min nonbonded
            # bonded list approx: skip pairs < 1.2 that are bonds; compute min over pairs >? Instead penalty
            score=D.min()
            # better: count pairs under 1.6 excluding known bonds -> use min of D excluding bonds
            if best is None or score>best[0]: best=(score,smeaz,ph_me,ph_sme)
print(best)
score,smeaz,ph_me,ph_sme=best
at=build(smeaz,np.deg2rad(ph_me),np.deg2rad(ph_sme))
with open('init.xyz','w') as f:
    f.write(f"{len(at)}\nTc(dmpe)2(SMe)2\n")
    for e,p in at: f.write(f"{e} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
pos=np.array([p for e,p in at]); els=[e for e,p in at]
for i,j in itertools.combinations(range(len(at)),2):
    r=np.linalg.norm(pos[i]-pos[j])
    if r<1.3 and not(els[i]=='H')!=(els[j]=='H'): pass
print("min H-H nonbonded check")
for i,j in itertools.combinations(range(len(at)),2):
    r=np.linalg.norm(pos[i]-pos[j])
    if els[i]=='H' and els[j]=='H' and r<1.5: print(i,j,round(r,2))
